using Eto.Forms; using Rhino.UI;
namespace RhinoContextAssist;
internal sealed class ContextAssistOptionsPage:OptionsDialogPage{readonly ContextAssistSettings settings;ContextAssistOptionsControl? control;public ContextAssistOptionsPage(ContextAssistSettings s):base("Context Assist")=>settings=s;public override object PageControl=>control??=new(settings);public override bool ShowApplyButton=>true;public override bool ShowDefaultsButton=>false;public override void OnApply(){control?.Apply();base.OnApply();}}
internal sealed class ContextAssistOptionsControl:Panel{
 readonly ContextAssistSettings settings;readonly CheckBox enabled=new(){Text="Context Assist aktivieren"};readonly DropDown position=new();readonly NumericStepper count=new(){MinValue=1,MaxValue=5,DecimalPlaces=0};readonly DropDown kind=new();readonly ListBox actions=new();readonly CheckBox actionEnabled=new(){Text="Aktion aktiviert"};readonly CheckBox favorite=new(){Text="Favorit (★)"};List<ActionPreference> current=new();
 public ContextAssistOptionsControl(ContextAssistSettings s){settings=s;position.Items.Add("Neben Mauszeiger");position.Items.Add("Neben Geometrie");foreach(var k in ActionCatalog.ConfigurableKinds)kind.Items.Add(Name(k));var up=new Button{Text="Nach oben"};var down=new Button{Text="Nach unten"};up.Click+=(_,_)=>Move(-1);down.Click+=(_,_)=>Move(1);kind.SelectedIndexChanged+=(_,_)=>LoadKind();actions.SelectedIndexChanged+=(_,_)=>LoadAction();actionEnabled.CheckedChanged+=(_,_)=>Edit();favorite.CheckedChanged+=(_,_)=>Edit();Content=new DynamicLayout{Padding=10,Spacing=new Eto.Drawing.Size(6,6),Rows={new DynamicRow(enabled),new DynamicRow(new Label{Text="Position"},position),new DynamicRow(new Label{Text="Anzahl Hauptaktionen"},count),new DynamicRow(new Label{Text="Objekttyp"},kind),new DynamicRow(actions),new DynamicRow(actionEnabled,favorite),new DynamicRow(up,down)}};Load();}
 void Load(){enabled.Checked=settings.Enabled;position.SelectedIndex=(int)settings.PositionMode;count.Value=settings.PrimaryCount;kind.SelectedIndex=0;LoadKind();}
 void LoadKind(){if(kind.SelectedIndex<0)return;var k=ActionCatalog.ConfigurableKinds[kind.SelectedIndex];current=settings.Preferences[k].Select(x=>new ActionPreference(x.Id,x.Enabled,x.Favorite)).ToList();RefreshList();}
 void RefreshList(){var k=ActionCatalog.ConfigurableKinds[kind.SelectedIndex];var map=ActionCatalog.Defaults(k).ToDictionary(x=>x.Id);actions.Items.Clear();foreach(var p in current)actions.Items.Add($"{(p.Favorite?"★ ":"")}{(p.Enabled?"☑":"☐")} {map[p.Id].Label}");if(current.Count>0)actions.SelectedIndex=0;}
 void LoadAction(){var i=actions.SelectedIndex;if(i<0||i>=current.Count)return;actionEnabled.Checked=current[i].Enabled;favorite.Checked=current[i].Favorite;}
 void Edit(){var i=actions.SelectedIndex;if(i<0||i>=current.Count)return;current[i]=current[i] with{Enabled=actionEnabled.Checked==true,Favorite=favorite.Checked==true};SaveCurrent();var keep=i;RefreshList();actions.SelectedIndex=keep;}
 void Move(int delta){var i=actions.SelectedIndex;var j=i+delta;if(i<0||j<0||j>=current.Count)return;(current[i],current[j])=(current[j],current[i]);SaveCurrent();RefreshList();actions.SelectedIndex=j;}
 void SaveCurrent(){var k=ActionCatalog.ConfigurableKinds[kind.SelectedIndex];settings.Preferences[k]=current.Select(x=>new ActionPreference(x.Id,x.Enabled,x.Favorite)).ToList();}
 public void Apply(){SaveCurrent();settings.Enabled=enabled.Checked==true;settings.PositionMode=(PopupPositionMode)Math.Max(0,position.SelectedIndex);settings.PrimaryCount=(int)count.Value;settings.Save();}
 static string Name(SelectionKind k)=>k switch{SelectionKind.PlanarBrepFace=>"Planare Teilfläche",SelectionKind.BrepFace=>"Teilfläche",SelectionKind.BrepEdge=>"Brep-Kante",SelectionKind.ClosedPlanarCurve=>"Geschlossene planare Kurve",SelectionKind.Curve=>"Kurve",SelectionKind.PlanarSurface=>"Planare Fläche",SelectionKind.Surface=>"Fläche",SelectionKind.SolidBrep=>"Geschlossener Körper",SelectionKind.Brep=>"Flächenverband",SelectionKind.Mesh=>"Mesh",SelectionKind.SubD=>"SubD",SelectionKind.Multiple=>"Mehrfachauswahl",SelectionKind.Mixed=>"Gemischte Auswahl",_=>k.ToString()};}
